111	  public HoodieRecord constructHoodieRecord(
112	      Option<IndexedRecord> recordOpt,
113	      Map<String, Object> metadataMap
114	  ) {
115	    String appliedPayloadClass =
116	        payloadClass.isPresent()
117	            ? payloadClass.get()
118	            : DefaultHoodieRecordPayload.class.getName();
119	    if (!recordOpt.isPresent()) {
120	      return SpillableMapUtils.generateEmptyPayload(
121	          (String) metadataMap.get(INTERNAL_META_RECORD_KEY),
122	          (String) metadataMap.get(INTERNAL_META_PARTITION_PATH),
123	          (Comparable<?>) metadataMap.get(INTERNAL_META_ORDERING_FIELD),
124	          appliedPayloadClass);
125	    }
126	    return new HoodieAvroIndexedRecord(recordOpt.get());
127	  }
