130	  public IndexedRecord seal(IndexedRecord record) {
131	    Schema schema = record.getSchema();
132	    GenericRecordBuilder builder = new GenericRecordBuilder(schema);
133	    for (Schema.Field field : schema.getFields()) {
134	      builder.set(field, record.get(field.pos()));
135	    }
136	    return builder.build();
137	  }
