112	    List<TypeInfo> dataColumnTypeList = dataColumnNameList.stream().map(fieldName -> {
113	      TypeInfo type = columnTypeMap.get(fieldName);
114	      if (type == null) {
115	        throw new IllegalArgumentException("Field: " + fieldName + ", does not have a defined type");
116	      }
117	      return type;
118	    }).collect(Collectors.toList());
119	    jobConf.set(serdeConstants.LIST_COLUMNS, String.join(",", dataColumnNameList));
120	    jobConf.set(serdeConstants.LIST_COLUMN_TYPES, dataColumnTypeList.stream().map(TypeInfo::getQualifiedName).collect(Collectors.joining(",")));
121	    // don't replace `f -> f.name()` with lambda reference
122	    String readColNames = requiredSchema.getFields().stream().map(f -> f.name()).collect(Collectors.joining(","));
123	    jobConf.set(ColumnProjectionUtils.READ_COLUMN_NAMES_CONF_STR, readColNames);
124	    jobConf.set(ColumnProjectionUtils.READ_COLUMN_IDS_CONF_STR, requiredSchema.getFields()
125	        .stream().map(f -> String.valueOf(dataSchema.getField(f.name()).pos())).collect(Collectors.joining(",")));
